758	def _w2_qr(data):
759	    A = data
760	    B, N, _ = A.shape
761	    H = A.clone()
762	    tau = torch.zeros((B, N), device=A.device, dtype=torch.float32)
763	
764	    if N <= 32:
765	        BLK = min(16, N)
766	    elif N >= 1536:
767	        # Tall panels (n>=2048): a narrow block halves the panel register
768	        # footprint -> much higher occupancy (~2x faster) than BLK=32.
769	        BLK = 16
770	    else:
771	        BLK = 32
772	
773	    Vbuf = torch.empty((B, BLK, N), device=A.device, dtype=torch.float32)
774	    Tbuf = torch.empty((B, BLK, BLK), device=A.device, dtype=torch.float32)
775	    YTbuf = torch.empty((B, BLK, N), device=A.device, dtype=torch.float32)
776	
777	    sab, san = H.stride(0), H.stride(1)
778	    svb, svk, svn = Vbuf.stride(0), Vbuf.stride(1), Vbuf.stride(2)
779	    stb, stk, stn = Tbuf.stride(0), Tbuf.stride(1), Tbuf.stride(2)
780	    syb, syk, syn = YTbuf.stride(0), YTbuf.stride(1), YTbuf.stride(2)
781	
782	    # Trailing-update tiles, tuned per-kernel via micro-sweep on representative
783	    # panels. The optimal tile is strongly batch/BLK-dependent because batch fills
784	    # the grid's program count:
785	    #   BLK==32 (n=176..1024, large/mid batch -> grid already saturated): small
786	    #       tiles win. YT BM=32/BNc=32/1w (205us vs 216us on B640); apply
787	    #       TALL-NARROW BM=128/BNc=32/4w (333us vs 395us, -16%) -- BNc==BLK avoids
788	    #       K-starving the K=32 MMA, tall BM reuses the loaded YT across rows.
789	    #   BLK<=16 (n>=2048, small batch B=2/8 -> grid starved): the YT must use a
790	    #       TALL reduction chunk + more warps to fill the SMs: BM=128/BNc=64/4w
791	    #       (45us vs 80us on n=4096, -44%); apply BM=32/BNc=32/2w (60us vs 70us).
792	    if BLK >= 32:
793	        BM_Y, BNc_Y, NW_Y = 32, 32, 1
794	        BM_A, BNc_A, NW_A = 128, 32, 4
795	    else:
796	        BM_Y, BNc_Y, NW_Y = 128, 64, 4
797	        BM_A, BNc_A, NW_A = 32, 32, 2
798	    j = 0
799	    while j < N:
800	        b = min(BLK, N - j)
801	        pheight = N - j
802	        MAXH = triton.next_power_of_2(pheight)
803	
804	        # num_warps must scale with the panel height: the panel kernel holds a
805	        # (MAXH, BLK) register tensor; too few warps -> register spill -> huge
806	        # slowdown (measured 7-10x on n>=1024). Empirically-tuned per MAXH.
807	        if MAXH <= 512:
808	            nwp = 4
809	        elif MAXH <= 1024:
810	            nwp = 8
811	        else:
812	            nwp = 32
813	
814	        _panel_factor_kernel[(B,)](
815	            H, tau, Vbuf, Tbuf,
816	            B, N, j, pheight, b,
817	            sab, san, svb, svk, svn, stb, stk, stn,
818	            BLK=BLK, MAXH=MAXH, num_warps=nwp,
819	        )
820	
821	        ncols = N - (j + b)
822	        if ncols > 0:
823	            nct_y = triton.cdiv(ncols, BNc_Y)
824	            _trailing_YT_kernel[(nct_y, B)](
825	                H, Vbuf, Tbuf, YTbuf,
826	                B, N, j, pheight, ncols, j + b,
827	                sab, san, svb, svk, svn, stb, stk, stn, syb, syk, syn,
828	                BLK=BLK, BM=BM_Y, BNc=BNc_Y, num_warps=NW_Y,
829	            )
830	            nct_a = triton.cdiv(ncols, BNc_A)
831	            nrt_a = triton.cdiv(pheight, BM_A)
832	            _trailing_apply_kernel[(nrt_a * nct_a, B)](
833	                H, Vbuf, YTbuf,
834	                B, N, j, pheight, ncols, j + b,
835	                sab, san, svb, svk, svn, syb, syk, syn,
836	                BLK=BLK, BM=BM_A, BNc=BNc_A, num_warps=NW_A,
837	            )
838	        j += b
839	
840	    return H, tau
841	
842	
843	def custom_kernel(data: input_t) -> output_t:
844	    n = data.shape[-1]
845	    # The custom one-block-per-matrix small-n kernel (_small_qr) is currently
846	    # SLOWER than the batch-major backend on every measured shape (n=32: 207 vs
847	    # 99us; n=176: 1085 vs 293us) -- its serial column sweep + low occupancy
848	    # lose to the backend's data-parallel-across-batch BLAS-3. Until the custom
849	    # kernel genuinely beats the backend on a given small n, route everything to
850	    # the batch-major backend; _SMALL_N holds the n values where _small_qr wins.
851	    if n <= 32:
852	        return _tiny_qr(data)
853	    if n in _SMALL_N:
854	        return _small_qr(data)
855	    return _w2_qr(data)
856	
857	
858	# n values for which the custom small-n kernel measurably beats the backend.
859	# Empty until a benchmark proves _small_qr faster on a specific n.
860	_SMALL_N = frozenset()
