// ===========================================================================
// qr_mega: ONE BLOCK per matrix, single-launch blocked (compact-WY) Householder
// QR. The whole right-looking factorization (panel factor + WY trailing update,
// all panels) runs inside ONE kernel launch -- no separate panel/trailing
// launches, so nothing serializes across the default execution queue. The
// matrix lives column-major in a global scratch (Acm); only the active panel
// and a trailing column chunk are staged in shared memory. Convention is
// bit-identical to torch.geqrf / LAPACK dlarfg.
//
// This is the NON-fused skeleton (group A == group B). The fused warp-
// specialized look-ahead variant (qr_mega_la) overlaps the next panel's serial
// reflector chain with the current panel's tensor-friendly trailing GEMM.
//
// NB   = panel width (reflectors per block step); NBMAX caps the register
//        arrays (pw/pz). CT = trailing column chunk staged per smem tile.
// Smem floats: n*NB (Ps) + NB*NB (Ts) + n*CT (Cs) + 2*NB*CT (Ws) + NB (taus)
//            + REDSZ (red) + NB (pww) + 8 (sval), REDSZ=max(8*NB, TPB).
// ===========================================================================
#define NBMAX 32
extern "C" __global__ void qr_mega(
    const float* __restrict__ A,     // (B,n,n) row-major input
    float* __restrict__ Acm,         // (B,n,n) column-major scratch
    float* __restrict__ H,           // (B,n,n) row-major output
    float* __restrict__ tau,         // (B,n)
    int B, int n, int NB, int CT)
{
    extern __shared__ float smem_m[];
    const int TPB = blockDim.x;
    const int REDSZ = (8 * NB > TPB) ? 8 * NB : TPB;
    float* Ps   = smem_m;                  // n*NB   current panel (col-major)
    float* Ts   = Ps + (long)n * NB;       // NB*NB  T (col-major Ts[i+l*NB])
    float* Cs   = Ts + NB * NB;            // n*CT   trailing chunk (col-major)
    float* Ws   = Cs + (long)n * CT;       // 2*NB*CT W and W' workspace
    float* taus = Ws + 2 * NB * CT;        // NB     panel tau values
    float* red  = taus + NB;               // REDSZ  reductions / warp partials
    float* pww  = red + REDSZ;             // NB     panel-update tau*w values
    float* sval = pww + NB;                // scalars

    const int tid = threadIdx.x;

    for (int bb = blockIdx.x; bb < B; bb += gridDim.x) {
        const float* Ab = A + (long)bb * n * n;
        float* Acmb = Acm + (long)bb * n * n;
        float* Hb = H + (long)bb * n * n;
        float* taub = tau + (long)bb * n;

        // row-major input -> column-major scratch
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n, c = idx % n;
            Acmb[(long)c * n + r] = Ab[(long)r * n + c];
        }
        __syncthreads();

        for (int p = 0; p < n; p += NB) {
            int nb = NB; if (p + nb > n) nb = n - p;

            // ---- load panel Acm[:, p:p+nb] into Ps (full height) ----
            for (int idx = tid; idx < n * nb; idx += TPB) {
                int j = idx / n, r = idx % n;
                Ps[(long)j * n + r] = Acmb[(long)(p + j) * n + r];
            }
            __syncthreads();

            // ---- panel factorization (unblocked, in smem) ----
            for (int j = 0; j < nb; ++j) {
                int c = p + j;
                float* pj = Ps + (long)j * n;
                float partial = 0.f;
                for (int r = c + tid; r < n; r += TPB) { float x = pj[r]; partial += x * x; }
                red[tid] = partial; __syncthreads();
                for (int s = TPB / 2; s > 0; s >>= 1) {
                    if (tid < s) red[tid] += red[tid + s];
                    __syncthreads();
                }
                if (tid == 0) {
                    float xnorm = sqrtf(red[0]);
                    float alpha = pj[c];
                    float beta = (alpha >= 0.f) ? -xnorm : xnorm;
                    float tval, invden;
                    if (xnorm > 0.f && (alpha - beta) != 0.f) {
                        tval = (beta - alpha) / beta;
                        invden = 1.f / (alpha - beta);
                    } else { tval = 0.f; invden = 0.f; beta = alpha; }
                    sval[0] = beta; sval[1] = tval; sval[2] = invden;
                }
                __syncthreads();
                float beta = sval[0], tval = sval[1], invden = sval[2];
                for (int r = c + 1 + tid; r < n; r += TPB) pj[r] = pj[r] * invden;
                __syncthreads();
                if (tid == 0) { pj[c] = 1.f; taus[j] = tval; }
                __syncthreads();
                int ntrail = nb - (j + 1);
                if (ntrail > 0) {
                    const int lane = tid & 31, warp = tid >> 5;
                    const int NWARP = TPB / 32;
                    float pw[NBMAX];
                    #pragma unroll
                    for (int t = 0; t < NBMAX; ++t) pw[t] = 0.f;
                    for (int r = c + tid; r < n; r += TPB) {
                        float vr = pj[r];
                        for (int t = 0; t < ntrail; ++t)
                            pw[t] += vr * Ps[(long)(j + 1 + t) * n + r];
                    }
                    for (int t = 0; t < ntrail; ++t) {
                        float v = pw[t];
                        #pragma unroll
                        for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
                        if (lane == 0) red[warp * NB + t] = v;
                    }
                    __syncthreads();
                    if (tid < ntrail) {
                        float w = 0.f;
                        for (int wi = 0; wi < NWARP; ++wi) w += red[wi * NB + tid];
                        pww[tid] = tval * w;
                    }
                    __syncthreads();
                    for (int t = 0; t < ntrail; ++t) {
                        float tw = pww[t];
                        float* pjj = Ps + (long)(j + 1 + t) * n;
                        for (int r = c + tid; r < n; r += TPB) pjj[r] -= tw * pj[r];
                    }
                    __syncthreads();
                }
                if (tid == 0) pj[c] = beta;
                __syncthreads();
            }

            // ---- build T (compact WY) ----
            for (int i = tid; i < nb; i += TPB) Ts[(long)i + (long)i * NB] = taus[i];
            __syncthreads();
            for (int l = 1; l < nb; ++l) {
                int cl = p + l;
                const float* Vl = Ps + (long)l * n;
                const int lane = tid & 31, warp = tid >> 5;
                const int NWARP = TPB / 32;
                float pz[NBMAX];
                #pragma unroll
                for (int t = 0; t < NBMAX; ++t) pz[t] = 0.f;
                for (int r = cl + tid; r < n; r += TPB) {
                    float vl = (r == cl) ? 1.f : Vl[r];
                    for (int i = 0; i < l; ++i) pz[i] += Ps[(long)i * n + r] * vl;
                }
                for (int i = 0; i < l; ++i) {
                    float v = pz[i];
                    #pragma unroll
                    for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
                    if (lane == 0) red[warp * NB + i] = v;
                }
                __syncthreads();
                if (tid < l) {
                    float zz = 0.f;
                    for (int wi = 0; wi < NWARP; ++wi) zz += red[wi * NB + tid];
                    Ws[tid] = zz;
                }
                __syncthreads();
                float tl = taus[l];
                for (int i = tid; i < l; i += TPB) {
                    float acc = 0.f;
                    for (int m = i; m < l; ++m) acc += Ts[(long)i + (long)m * NB] * Ws[m];
                    Ts[(long)i + (long)l * NB] = -tl * acc;
                }
                __syncthreads();
            }

            // ---- trailing update: cols [p+nb, n) in chunks of CT ----
            int tstart = p + nb;
            for (int g0 = tstart; g0 < n; g0 += CT) {
                int ct = CT; if (g0 + ct > n) ct = n - g0;
                for (int idx = tid; idx < n * ct; idx += TPB) {
                    int g = idx / n, r = idx % n;
                    Cs[(long)g * n + r] = Acmb[(long)(g0 + g) * n + r];
                }
                __syncthreads();
                // W = V^T C
                int ng2 = (ct + 1) / 2;
                for (int idx = tid; idx < nb * ng2; idx += TPB) {
                    int gt = idx / nb, i = idx % nb;
                    int gg = gt * 2;
                    bool hg1 = (gg + 1 < ct);
                    int ci = p + i;
                    const float* Vi = Ps + (long)i * n;
                    const float* C0 = Cs + (long)gg * n;
                    const float* C1 = Cs + (long)(gg + 1) * n;
                    float s0 = C0[ci];
                    float s1 = hg1 ? C1[ci] : 0.f;
                    float t0 = 0.f, t1 = 0.f;
                    int r = ci + 1;
                    for (; r + 1 < n; r += 2) {
                        float v0 = Vi[r], v1 = Vi[r + 1];
                        s0 += v0 * C0[r];     t0 += v1 * C0[r + 1];
                        if (hg1) { s1 += v0 * C1[r]; t1 += v1 * C1[r + 1]; }
                    }
                    for (; r < n; ++r) {
                        float v0 = Vi[r];
                        s0 += v0 * C0[r];
                        if (hg1) s1 += v0 * C1[r];
                    }
                    Ws[(long)i + (long)gg * NB] = s0 + t0;
                    if (hg1) Ws[(long)i + (long)(gg + 1) * NB] = s1 + t1;
                }
                __syncthreads();
                // W' = T^T W
                for (int idx = tid; idx < nb * ct; idx += TPB) {
                    int g = idx / nb, i = idx % nb;
                    float acc = 0.f;
                    for (int l = 0; l <= i; ++l)
                        acc += Ts[(long)l + (long)i * NB] * Ws[(long)l + (long)g * NB];
                    Ws[(long)NB * CT + (long)i + (long)g * NB] = acc;
                }
                __syncthreads();
                // C -= V W'
                const float* Wp = Ws + (long)NB * CT;
                int nrows = n - p;
                int ng4 = (ct + 3) / 4;
                for (int idx = tid; idx < nrows * ng4; idx += TPB) {
                    int gt = idx / nrows;
                    int rr = idx % nrows;
                    int r = p + rr;
                    int g0c = gt * 4;
                    float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;
                    bool h1 = (g0c + 1 < ct), h2 = (g0c + 2 < ct), h3 = (g0c + 3 < ct);
                    for (int i = 0; i < nb; ++i) {
                        int ci = p + i;
                        if (r < ci) break;
                        float vi = (r == ci) ? 1.f : Ps[(long)i * n + r];
                        const float* Wpi = Wp + i;
                        acc0 += vi * Wpi[(long)(g0c) * NB];
                        if (h1) acc1 += vi * Wpi[(long)(g0c + 1) * NB];
                        if (h2) acc2 += vi * Wpi[(long)(g0c + 2) * NB];
                        if (h3) acc3 += vi * Wpi[(long)(g0c + 3) * NB];
                    }
                    Cs[(long)(g0c) * n + r] -= acc0;
                    if (h1) Cs[(long)(g0c + 1) * n + r] -= acc1;
                    if (h2) Cs[(long)(g0c + 2) * n + r] -= acc2;
                    if (h3) Cs[(long)(g0c + 3) * n + r] -= acc3;
                }
                __syncthreads();
                for (int idx = tid; idx < n * ct; idx += TPB) {
                    int g = idx / n, r = idx % n;
                    Acmb[(long)(g0 + g) * n + r] = Cs[(long)g * n + r];
                }
                __syncthreads();
            }

            // ---- write panel back to global scratch ----
            for (int idx = tid; idx < n * nb; idx += TPB) {
                int j = idx / n, r = idx % n;
                Acmb[(long)(p + j) * n + r] = Ps[(long)j * n + r];
            }
            for (int j = tid; j < nb; j += TPB) taub[p + j] = taus[j];
            __syncthreads();
        }

        // write H row-major from column-major scratch
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n, c = idx % n;
            Hb[(long)r * n + c] = Acmb[(long)c * n + r];
        }
        __syncthreads();
    }
}
