// ===========================================================================
// qr_mega_la: FUSED warp-specialized LOOK-AHEAD blocked QR. One block per
// matrix, single launch. Hides the panel's serial Householder latency behind
// the bulk WY trailing GEMM by overlapping them WITHIN one launch:
//
//   factor panel[0]
//   for p = 0, NB, 2NB, ...:
//     np = p + nb (next panel start)
//     PHASE 1 (all warps): apply WY(V_p,T_p) to ONLY the next panel's columns
//             [np, np+nbn) -> staged + factored-ready in P[nxt].
//     PHASE 2 (warp-specialized, CONCURRENT):
//       group A (first WA warps): factor panel[np] in P[nxt]  (serial chain)
//       group B (rest):           apply WY(V_p,T_p) to the BULK trailing cols
//                                 [np+nbn, n) reading/writing global Acm.
//       Group A and B run concurrently, each using its OWN named barrier
//       (bar.sync id,count) -- NO whole-block __syncthreads in the overlap, so
//       group B's tensor-friendly GEMM hides group A's serial latency.
//     rejoin (__syncthreads); write panel[p] back to global; ping-pong buffers.
//
// Two panel smem buffers P[0]/P[1] ping-pong (current source vs. next-being-
// factored). Convention bit-identical to torch.geqrf / LAPACK dlarfg.
//
// Smem layout (floats), with two panels + group-B trailing buffers + per-group
// scratch:
//   P0[n*NB], P1[n*NB], T0[NB*NB], T1[NB*NB], tau0[NB], tau1[NB],
//   Cs[n*CT], Ws[2*NB*CT]            (group B trailing)
//   redB[REDB], redA[REDA], sA[8]    (per-group reductions / scalars)
// REDB = WB*NB (warp partials for group B's W reduce, WB = group-B warps),
// REDA = WA*NB.
// ===========================================================================
extern "C" __global__ void qr_mega_la(
    const float* __restrict__ A,
    float* __restrict__ Acm,
    float* __restrict__ H,
    float* __restrict__ tau,
    int B, int n, int NB, int CT, int WA)   // WA = #warps in group A (panel)
{
    extern __shared__ float smem_la[];
    const int TPB = blockDim.x;
    const int NWARP = TPB >> 5;
    const int WB = NWARP - WA;                  // group-B warps (trailing)
    const int TA = WA * 32;                     // group-A thread count
    const int TB = WB * 32;                     // group-B thread count
    const int REDA = WA * NB;
    const int REDB = WB * NB;

    float* P0   = smem_la;                       // n*NB
    float* P1   = P0 + (long)n * NB;             // n*NB
    float* T0   = P1 + (long)n * NB;             // NB*NB
    float* T1   = T0 + NB * NB;                  // NB*NB
    float* tau0 = T1 + NB * NB;                  // NB
    float* tau1 = tau0 + NB;                     // NB
    float* Cs   = tau1 + NB;                     // n*CT
    float* Ws   = Cs + (long)n * CT;             // 2*NB*CT
    float* redB = Ws + 2 * NB * CT;              // REDB
    float* redA = redB + REDB;                   // REDA
    float* sA   = redA + REDA;                   // 8  (panel-factor scalars)

    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const bool inA = (warp < WA);
    const int laneA = tid;                       // group-A threads are [0,TA)
    const int warpA = warp;                      // group-A warp index
    const int tidB = tid - TA;                   // group-B local thread [0,TB)
    const int warpB = warp - WA;                 // group-B warp index

    for (int bb = blockIdx.x; bb < B; bb += gridDim.x) {
        const float* Ab = A + (long)bb * n * n;
        float* Acmb = Acm + (long)bb * n * n;
        float* Hb = H + (long)bb * n * n;
        float* taub = tau + (long)bb * n;

        // row-major input -> column-major scratch
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n, c = idx % n;
            Acmb[(long)c * n + r] = Ab[(long)r * n + c];
        }
        __syncthreads();

        // ---- factor panel[0] into P0 (all threads) ----
        {
            int nb0 = NB; if (nb0 > n) nb0 = n;
            for (int idx = tid; idx < n * nb0; idx += TPB) {
                int j = idx / n, r = idx % n;
                P0[(long)j * n + r] = Acmb[(long)j * n + r];
            }
            __syncthreads();
            qr_la_factor_panel(P0, T0, tau0, redB, sA, 0, nb0, n, tid, TPB, NWARP, NB);
            __syncthreads();
        }

        int cur = 0;                              // buffer holding current panel
        for (int p = 0; p < n; p += NB) {
            int nb = NB; if (p + nb > n) nb = n - p;
            int np = p + nb;
            int nxt = 1 - cur;
            bool has_next = (np < n);
            int nbn = 0;
            if (has_next) { nbn = NB; if (np + nbn > n) nbn = n - np; }

            float* Pcur = (cur == 0) ? P0 : P1;
            float* Tcur = (cur == 0) ? T0 : T1;
            float* Pnxt = (nxt == 0) ? P0 : P1;
            float* Tnxt = (nxt == 0) ? T0 : T1;
            float* taunxt = (nxt == 0) ? tau0 : tau1;

            // ---- PHASE 1 (all warps): WY(Pcur,Tcur) applied to next panel
            //      columns [np, np+nbn), staged into Pnxt (full height). ----
            if (has_next) {
                // load next-panel columns from global into Pnxt
                for (int idx = tid; idx < n * nbn; idx += TPB) {
                    int g = idx / n, r = idx % n;
                    Pnxt[(long)g * n + r] = Acmb[(long)(np + g) * n + r];
                }
                __syncthreads();
                // W = V^T Pnxt  (V = Pcur, panel at column-base p, height from p)
                //   W[i,g] = sum_{r>=p+i? actually r>=p, V unit-diag} ...
                // reuse generic apply: treat Pnxt as the trailing chunk of width nbn.
                qr_la_apply_wy(Pcur, Tcur, Pnxt, Ws, p, nb, nbn, n, tid, TPB, NB, CT);
                __syncthreads();
            }

            // ---- PHASE 2 (warp-specialized, concurrent) ----
            //   group A: factor panel[np] in Pnxt  (only if has_next)
            //   group B: bulk WY(Pcur,Tcur) on cols [np+nbn, n)
            if (inA) {
                if (has_next) {
                    qr_la_factor_panel(Pnxt, Tnxt, taunxt, redA, sA,
                                       np, nbn, n, laneA, TA, WA, NB);
                }
            } else {
                int g0start = np + nbn;
                if (g0start < n) {
                    qr_la_bulk_trailing(Acmb, Pcur, Tcur, Cs, Ws, redB,
                                        p, nb, g0start, n, tidB, TB, WB, NB, CT);
                }
            }
            __syncthreads();

            // ---- write panel[p] (Pcur) back to global; store tau ----
            float* taucur = (cur == 0) ? tau0 : tau1;
            for (int idx = tid; idx < n * nb; idx += TPB) {
                int j = idx / n, r = idx % n;
                Acmb[(long)(p + j) * n + r] = Pcur[(long)j * n + r];
            }
            for (int j = tid; j < nb; j += TPB) taub[p + j] = taucur[j];
            __syncthreads();

            cur = nxt;
        }

        // write H row-major from column-major scratch
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n, c = idx % n;
            Hb[(long)r * n + c] = Acmb[(long)c * n + r];
        }
        __syncthreads();
    }
}
