                if (lane == 0) red[warp * NB + u] = v;
            }
            grp_bar(barid, nthr);
            // thread u (u<ntrail) sums nwarp partials -> tau*w[u] stored in sv[8+u]
            if (t < ntrail) {
                float w = 0.f;
                for (int w2 = 0; w2 < nwarp; ++w2) w += red[w2 * NB + t];
                sv[8 + t] = tval * w;
            }
            grp_bar(barid, nthr);
            for (int u = 0; u < ntrail; ++u) {
                float tw = sv[8 + u];
                float* pjj = P + (long)(j + 1 + u) * n;
                for (int r = c + t; r < n; r += nthr) pjj[r] -= tw * pj[r];
            }
            grp_bar(barid, nthr);
        }
        if (t == 0) pj[c] = beta;
        grp_bar(barid, nthr);
    }
    // build T (compact WY): T[i,i]=taus[i]; T[0:l,l] = -taus[l]*(T[0:l,0:l] @ z)
    for (int i = t; i < nb; i += nthr) Tm[(long)i + (long)i * NB] = taus[i];
    grp_bar(barid, nthr);
    for (int l = 1; l < nb; ++l) {
        int cl = p + l;
        const float* Vl = P + (long)l * n;
        float pz[NBMAX];
        #pragma unroll
        for (int u = 0; u < NBMAX; ++u) pz[u] = 0.f;
        for (int r = cl + t; r < n; r += nthr) {
            float vl = (r == cl) ? 1.f : Vl[r];
            for (int i = 0; i < l; ++i) pz[i] += P[(long)i * n + r] * vl;
        }
        for (int i = 0; i < l; ++i) {
            float v = pz[i];
            #pragma unroll
            for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
            if (lane == 0) red[warp * NB + i] = v;
        }
        grp_bar(barid, nthr);
        // z[i] in sv[8+i]
        if (t < l) {
            float zz = 0.f;
            for (int w2 = 0; w2 < nwarp; ++w2) zz += red[w2 * NB + t];
            sv[8 + t] = zz;
        }
        grp_bar(barid, nthr);
        float tl = taus[l];
        for (int i = t; i < l; i += nthr) {
            float acc = 0.f;
            for (int m = i; m < l; ++m) acc += Tm[(long)i + (long)m * NB] * sv[8 + m];
            Tm[(long)i + (long)l * NB] = -tl * acc;
        }
        grp_bar(barid, nthr);
    }
}

// Apply WY(V=P, T=Tm) to a trailing column block held FULLY in smem buffer C
// (column-major, full height n, `ct` columns; their global column-base is gbase
// but C is self-contained). V is the panel at column-base p, width nb. Updates
// C in place: C -= V (T^T (V^T C)). Uses Ws (>= 2*NB*CT) as W/W' workspace.
// Full-block barrier (barid implied by caller via __syncthreads outside); this
// routine itself uses grp_bar(barid,nthr).
static __device__ void qr_la_apply_wy(
    float* P, float* Tm, float* C, float* Ws,
    int p, int nb, int ct, int n, int t, int nthr, int NB, int CT, int barid)
{
    // W[i,g] = sum_{r>=p} V[r,i] * C[r,g]  (V unit-diag at row p+i)
    for (int idx = t; idx < nb * ct; idx += nthr) {
        int g = idx / nb, i = idx % nb;
        int ci = p + i;
        const float* Vi = P + (long)i * n;
        const float* Cg = C + (long)g * n;
        float s = Cg[ci];                  // V[ci,i]=1 term
        for (int r = ci + 1; r < n; ++r) s += Vi[r] * Cg[r];
        Ws[(long)i + (long)g * NB] = s;
    }
    grp_bar(barid, nthr);
    // W'[i,g] = sum_{l<=i} T[l,i] W[l,g]
    for (int idx = t; idx < nb * ct; idx += nthr) {
        int g = idx / nb, i = idx % nb;
        float acc = 0.f;
        for (int l = 0; l <= i; ++l) acc += Tm[(long)l + (long)i * NB] * Ws[(long)l + (long)g * NB];
        Ws[(long)NB * CT + (long)i + (long)g * NB] = acc;
    }
    grp_bar(barid, nthr);
    // C[r,g] -= sum_i V[r,i] W'[i,g]   (r >= p, V unit-diag)
    const float* Wp = Ws + (long)NB * CT;
    int nrows = n - p;
    for (int idx = t; idx < nrows * ct; idx += nthr) {
        int g = idx / nrows, rr = idx % nrows;
        int r = p + rr;
        float acc = 0.f;
        for (int i = 0; i < nb; ++i) {
            int ci = p + i;
            if (r < ci) break;
            float vi = (r == ci) ? 1.f : P[(long)i * n + r];
            acc += vi * Wp[(long)i + (long)g * NB];
        }
        C[(long)g * n + r] -= acc;
    }
    grp_bar(barid, nthr);
}

// Group-B bulk trailing update: apply WY(V=P, T=Tm) to GLOBAL columns
// [g0start, n) of Acmb, in chunks of CT staged into Cs. Self-contained: reads
// chunk from global, applies, writes back. `t` group-local in [0,nthr).
static __device__ void qr_la_bulk_trailing(
    float* Acmb, float* P, float* Tm, float* Cs, float* Ws, float* red,
    int p, int nb, int g0start, int n, int t, int nthr, int nwarp, int NB, int CT, int barid)
{
    for (int g0 = g0start; g0 < n; g0 += CT) {
        int ct = CT; if (g0 + ct > n) ct = n - g0;
        for (int idx = t; idx < n * ct; idx += nthr) {
            int g = idx / n, r = idx % n;
            Cs[(long)g * n + r] = Acmb[(long)(g0 + g) * n + r];
        }
        grp_bar(barid, nthr);
        qr_la_apply_wy(P, Tm, Cs, Ws, p, nb, ct, n, t, nthr, NB, CT, barid);
        // apply_wy ends with a grp_bar; chunk is updated. write back.
        for (int idx = t; idx < n * ct; idx += nthr) {
            int g = idx / n, r = idx % n;
            Acmb[(long)(g0 + g) * n + r] = Cs[(long)g * n + r];
        }
        grp_bar(barid, nthr);
    }
}


