static __device__ void qr_la_apply_wy(
    float* P, float* Tm, float* C, float* Ws,
    int p, int nb, int ct, int n, int t, int nthr, int NB, int wscols, int barid)
{
    // W[i,g] = sum_{r>=p} V[r,i] * C[r,g]  (V unit-diag at row p+i). G-tile by 2:
    // load V[r,i] once, reuse across two adjacent chunk columns.
    int ng2 = (ct + 1) / 2;
    for (int idx = t; idx < nb * ng2; idx += nthr) {
        int gt = idx / nb, i = idx % nb;
        int gg = gt * 2;
        bool hg1 = (gg + 1 < ct);
        int ci = p + i;
        const float* Vi = P + (long)i * n;
        const float* C0 = C + (long)gg * n;
        const float* C1 = C + (long)(gg + 1) * n;
        float s0 = C0[ci];
        float s1 = hg1 ? C1[ci] : 0.f;
        float u0 = 0.f, u1 = 0.f;
        int r = ci + 1;
        for (; r + 1 < n; r += 2) {
            float v0 = Vi[r], v1 = Vi[r + 1];
            s0 += v0 * C0[r];     u0 += v1 * C0[r + 1];
            if (hg1) { s1 += v0 * C1[r]; u1 += v1 * C1[r + 1]; }
        }
        for (; r < n; ++r) {
            float v0 = Vi[r];
            s0 += v0 * C0[r];
            if (hg1) s1 += v0 * C1[r];
        }
        Ws[(long)i + (long)gg * NB] = s0 + u0;
        if (hg1) Ws[(long)i + (long)(gg + 1) * NB] = s1 + u1;
    }
    grp_bar(barid, nthr);
    // W'[i,g] = sum_{l<=i} T[l,i] W[l,g]
    for (int idx = t; idx < nb * ct; idx += nthr) {
        int g = idx / nb, i = idx % nb;
        float acc = 0.f;
        for (int l = 0; l <= i; ++l) acc += Tm[(long)l + (long)i * NB] * Ws[(long)l + (long)g * NB];
        Ws[(long)NB * wscols + (long)i + (long)g * NB] = acc;
    }
    grp_bar(barid, nthr);
    // C[r,g] -= sum_i V[r,i] W'[i,g]   (r >= p, V unit-diag). G-tile by 4: load
    // V[r,i] once, reuse across 4 chunk columns.
    const float* Wp = Ws + (long)NB * wscols;
    int nrows = n - p;
    int ng4 = (ct + 3) / 4;
    for (int idx = t; idx < nrows * ng4; idx += nthr) {
        int gt = idx / nrows, rr = idx % nrows;
        int r = p + rr;
        int g0c = gt * 4;
        float a0 = 0.f, a1 = 0.f, a2 = 0.f, a3 = 0.f;
        bool h1 = (g0c + 1 < ct), h2 = (g0c + 2 < ct), h3 = (g0c + 3 < ct);
        for (int i = 0; i < nb; ++i) {
            int ci = p + i;
            if (r < ci) break;
            float vi = (r == ci) ? 1.f : P[(long)i * n + r];
            const float* Wpi = Wp + i;
            a0 += vi * Wpi[(long)(g0c) * NB];
            if (h1) a1 += vi * Wpi[(long)(g0c + 1) * NB];
            if (h2) a2 += vi * Wpi[(long)(g0c + 2) * NB];
            if (h3) a3 += vi * Wpi[(long)(g0c + 3) * NB];
        }
        C[(long)(g0c) * n + r] -= a0;
        if (h1) C[(long)(g0c + 1) * n + r] -= a1;
        if (h2) C[(long)(g0c + 2) * n + r] -= a2;
        if (h3) C[(long)(g0c + 3) * n + r] -= a3;
    }
    grp_bar(barid, nthr);
}

