// ---------------------------------------------------------------------------
// Group barrier: bar.sync <id>, <nthr>. id=0 with nthr==blockDim is exactly
// __syncthreads(); id=1/2 synchronize a NAMED subset (group A / group B), so
// the two warp-specialized groups can each barrier among themselves WITHOUT a
// whole-block sync (which would deadlock the overlap). nthr must be a multiple
// of warp size.
// ---------------------------------------------------------------------------
static __device__ __forceinline__ void grp_bar(int barid, int nthr) {
    asm volatile("bar.sync %0, %1;" :: "r"(barid), "r"(nthr) : "memory");
}

