        // Use: each lane writes its fragment elements. store_matrix_sync writes
        // the full tile; we need Cs -= acc. Do: store acc to a per-warp smem buf.
        // -> handled by caller-provided staging via store then SIMT subtract.
        wmma::store_matrix_sync(Cs + (long)mi * 16 + (long)ni * 16 * n, acc, n,
                                wmma::mem_col_major);
    }
    grp_bar(barid, nthr);
}

