// ===========================================================================
// qr_mega_la_tc: fused warp-specialized look-ahead QR with a tf32x3 TENSOR-CORE
// trailing GEMM for group B (qr_la_trailing_tc). Same overlap structure as
// qr_mega_la, but: (1) panel[p] is written back to global BEFORE the overlap so
// (2) Pcur can be converted in place to the CLEAN reflector matrix (diag 1, rows
// above the panel diagonal zeroed) that WMMA consumes directly; (3) each group-B
// chunk is staged zero-padded to a multiple of 16 columns for the 16x16 tiles.
// Convention bit-identical to torch.geqrf / LAPACK dlarfg.
// ===========================================================================
extern "C" __global__ void qr_mega_la_tc(
    const float* __restrict__ A,
    float* __restrict__ Acm,
    float* __restrict__ H,
    float* __restrict__ tau,
    int B, int n, int NB, int CT, int WA)
{
    extern __shared__ float smem_lt[];
    const int TPB = blockDim.x;
    const int NWARP = TPB >> 5;
    const int WA2 = WA;
    const int WB = NWARP - WA2;
    const int TA = WA2 * 32;
    const int TB = WB * 32;
    const int REDA = WA2 * NB;
    const int REDB = NWARP * NB;
    const int WSCOLS = (CT > NB) ? CT : NB;
    const int CTP = ((CT + 15) / 16) * 16;       // padded chunk width (mult of 16)

    float* P0   = smem_lt;                        // n*NB
    float* P1   = P0 + (long)n * NB;              // n*NB
    float* T0   = P1 + (long)n * NB;              // NB*NB
    float* T1   = T0 + NB * NB;                   // NB*NB
    float* tau0 = T1 + NB * NB;                   // NB
    float* tau1 = tau0 + NB;                      // NB
    float* Cs   = tau1 + NB;                      // n*CTP  (padded)
    float* Ws   = Cs + (long)n * CTP;             // 2*NB*WSCOLS
    float* redB = Ws + 2 * NB * WSCOLS;           // REDB
    float* redA = redB + REDB;                    // REDA
    float* sA   = redA + REDA;                    // 8+NB

    const int tid = threadIdx.x;
    const int warp = tid >> 5;
    const bool inA = (warp < WA2);
    const int laneA = tid;
    const int tidB = tid - TA;

    for (int bb = blockIdx.x; bb < B; bb += gridDim.x) {
        const float* Ab = A + (long)bb * n * n;
        float* Acmb = Acm + (long)bb * n * n;
        float* Hb = H + (long)bb * n * n;
        float* taub = tau + (long)bb * n;

        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n, c = idx % n;
            Acmb[(long)c * n + r] = Ab[(long)r * n + c];
        }
        __syncthreads();

        {
            int nb0 = NB; if (nb0 > n) nb0 = n;
            for (int idx = tid; idx < n * nb0; idx += TPB) {
                int j = idx / n, r = idx % n;
                P0[(long)j * n + r] = Acmb[(long)j * n + r];
            }
            __syncthreads();
            qr_la_factor_panel(P0, T0, tau0, redB, sA, 0, nb0, n, tid, TPB, NWARP, NB, 0);
            __syncthreads();
        }

        int cur = 0;
        for (int p = 0; p < n; p += NB) {
            int nb = NB; if (p + nb > n) nb = n - p;
            int np = p + nb;
            int nxt = 1 - cur;
            bool has_next = (np < n);
            int nbn = 0;
            if (has_next) { nbn = NB; if (np + nbn > n) nbn = n - np; }

            float* Pcur = (cur == 0) ? P0 : P1;
            float* Tcur = (cur == 0) ? T0 : T1;
            float* Pnxt = (nxt == 0) ? P0 : P1;
            float* Tnxt = (nxt == 0) ? T0 : T1;
            float* taunxt = (nxt == 0) ? tau0 : tau1;
            float* taucur = (cur == 0) ? tau0 : tau1;

            // ---- PHASE 1 (all warps): SIMT WY of Pcur applied to next panel
            //      cols [np, np+nbn) staged into Pnxt. ----
            if (has_next) {
                for (int idx = tid; idx < n * nbn; idx += TPB) {
                    int g = idx / n, r = idx % n;
                    Pnxt[(long)g * n + r] = Acmb[(long)(np + g) * n + r];
                }
                __syncthreads();
                qr_la_apply_wy(Pcur, Tcur, Pnxt, Ws, p, nb, nbn, n, tid, TPB, NB, WSCOLS, 0);
                __syncthreads();
            }

            // ---- write panel[p] (Pcur, R intact) back to global; store tau ----
            for (int idx = tid; idx < n * nb; idx += TPB) {
                int j = idx / n, r = idx % n;
                Acmb[(long)(p + j) * n + r] = Pcur[(long)j * n + r];
            }
            for (int j = tid; j < nb; j += TPB) taub[p + j] = taucur[j];
            __syncthreads();

            // ---- convert Pcur in place to CLEAN reflector V: diag=1, rows above
            //      the panel diagonal zeroed (R already saved above). ----
            for (int idx = tid; idx < n * nb; idx += TPB) {
                int j = idx / n, r = idx % n;
                int cj = p + j;
                float v;
                if (r == cj) v = 1.0f;
                else if (r > cj) v = Pcur[(long)j * n + r];
                else v = 0.0f;
                Pcur[(long)j * n + r] = v;
            }
            __syncthreads();

            // ---- PHASE 2 (warp-specialized, concurrent) ----
            //   group A: factor panel[np] in Pnxt
            //   group B: tf32x3 tensor-core WY of clean Pcur on cols [np+nbn, n),
            //            chunked, staged zero-padded to CTP columns.
            if (inA) {
                if (has_next) {
                    qr_la_factor_panel(Pnxt, Tnxt, taunxt, redA, sA,
                                       np, nbn, n, laneA, TA, WA2, NB, 1);
                }
            } else {
                int g0start = np + nbn;
                for (int g0 = g0start; g0 < n; g0 += CT) {
                    int ct = CT; if (g0 + ct > n) ct = n - g0;
                    // stage chunk (zero-pad cols [ct, CTP))
                    for (int idx = tidB; idx < n * CTP; idx += TB) {
                        int g = idx / n, r = idx % n;
                        float v = (g < ct) ? Acmb[(long)(g0 + g) * n + r] : 0.0f;
                        Cs[(long)g * n + r] = v;
                    }
                    grp_bar(2, TB);
                    qr_la_trailing_tc(Pcur, Tcur, Cs, Ws, p, nb, CTP, n, tidB, TB,
                                      NB, WSCOLS, 2);
                    // write back valid cols only
                    for (int idx = tidB; idx < n * ct; idx += TB) {
                        int g = idx / n, r = idx % n;
                        Acmb[(long)(g0 + g) * n + r] = Cs[(long)g * n + r];
                    }
                    grp_bar(2, TB);
                }
            }
            __syncthreads();

            cur = nxt;
        }

        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n, c = idx % n;
            Hb[(long)r * n + c] = Acmb[(long)c * n + r];
        }
        __syncthreads();
    }
}
